query IssueLinks($owner: String!, $repo: String!, $number: Int!, $link0Owner: String!, $link0Repo: String!, $link0Number: Int!, $link1Owner: String!, $link1Repo: String!, $link1Number: Int!) {
  repository(owner: $owner, name: $repo) {
    issueOrPullRequest(number: $number) { __typename ... on Issue { id title blockedBy(first: 50) { nodes { id } } } }
  }
  link0: repository(owner: $link0Owner, name: $link0Repo) {
    issueOrPullRequest(number: $link0Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } blockedBy(first: 50) { nodes { id } } } }
  }
  link1: repository(owner: $link1Owner, name: $link1Repo) {
    issueOrPullRequest(number: $link1Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } blockedBy(first: 50) { nodes { id } } } }
  }
}

mutation Unblock($issue: ID!, $link0: ID!) {
  link0: removeBlockedBy(input: {issueId: $issue, blockingIssueId: $link0}) { issue { id } }
}

